<?php
function nowiso():string{return (new DateTimeImmutable('now',new DateTimeZone('UTC')))->format('Y-m-d\TH:i:s.v\Z');}
function elapsed(array $r):int{$n=0;foreach($r['timeSessions']??[] as $s)$n+=max(0,((isset($s['end'])?strtotime($s['end']):time())-strtotime($s['start'])));return $n;}
function running(array $r):bool{foreach($r['timeSessions']??[] as $s)if(empty($s['end']))return true;return false;}
function paidamount(array $r):int{$n=0;foreach(array_merge($r['cashPayments']??[],$r['stripePayments']??[]) as $p)$n+=$p['amount'];return ($r['status']??'')==='Paid'&&!count($r['cashPayments']??[])&&!count($r['stripePayments']??[])?$r['total']:$n;}
function paymentlocked(array $r):bool{return !empty($r['sessionId'])||!empty($r['checkoutPending'])||!empty($r['cashPayments'])||!empty($r['stripePayments'])||($r['status']??'')==='Paid';}
function paystatus(array $r):string{$r['status']='Unpaid';$n=paidamount($r);return $n>=$r['total']?'Paid':($n>0?'Partially paid':'Unpaid');}
function methodlabel(array $r):string{return !empty($r['cashPayments'])?(!empty($r['stripePayments'])?'Cash and Stripe':'Cash'):'Stripe';}
function operation(mixed $id):void{if(!is_string($id)||!preg_match('/^[a-f0-9-]{36}$/i',$id))throw new InvalidArgumentException('Invalid operation reference.');}
function workupdate(array $r,string $action,string $id,mixed $rate=null,?string $status=null,?string $now=null):array{
 if(!in_array($r['kind'],['estimate','invoice'],true))throw new InvalidArgumentException('Estimate or invoice not found.');operation($id);$now=$now??nowiso();$sessions=$r['timeSessions']??[];$active=null;foreach($sessions as $i=>$s)if(empty($s['end']))$active=$i;
 if($action==='status'){if(!in_array($status,['Scheduled','Diagnosing','Waiting on parts','Working on vehicle','Completed','Cancelled'],true))throw new InvalidArgumentException('Select repair progress.');if($active!==null&&in_array($status,['Completed','Cancelled']))throw new InvalidArgumentException('Clock out before completing the work.');$r['repairStatus']=$status;$r['updatedAt']=$now;return $r;}
 foreach($sessions as $s)if(($action==='start'&&$s['id']===$id)||($action==='stop'&&($s['stopId']??'')===$id))return $r;
 if(paymentlocked($r))throw new InvalidArgumentException('This invoice is locked by payments or a payment link.');
 if($action==='start'){if($active!==null)throw new InvalidArgumentException('Already clocked in.');$rate=count($sessions)?($r['hourlyRate']??null):$rate;if(!numeric($rate)||$rate<=0||$rate>100000)throw new InvalidArgumentException('Enter your labor rate before clocking in.');$r['hourlyRate']=$rate;$sessions[]=['id'=>$id,'start'=>$now];}
 elseif($action==='stop'){if($active===null)throw new InvalidArgumentException('Not clocked in.');$sessions[$active]['end']=$now;$sessions[$active]['stopId']=$id;$r['timeSessions']=$sessions;$hours=max(.01,round(elapsed($r)/3600,2));$line=['description'=>'Labor (tracked time)','unit'=>'hrs','qty'=>$hours,'price'=>$r['hourlyRate'],'trackedDocumentId'=>$r['id']];$found=false;foreach($r['lines'] as &$l)if(($l['trackedDocumentId']??'')===$r['id']){$l=$line;$found=true;}unset($l);if(!$found)$r['lines'][]=$line;$r['total']=total($r);if($r['total']>99999999)throw new InvalidArgumentException('Total is out of range.');}
 else throw new InvalidArgumentException('Invalid timer action.');$r['timeSessions']=$sessions;$r['updatedAt']=$now;return $r;
}
function invoicefromestimate(array $e,array $i):array{foreach(['customerId','customer','phone','email','vehicle','identifier','address','issue','notes','tax','discount','repairStatus'] as $k){if(array_key_exists($k,$e))$i[$k]=$e[$k];else unset($i[$k]);}if(empty($i['timeSessions']))$i['hourlyRate']=$e['hourlyRate']??0;$own=array_values(array_filter($i['lines']??[],fn($l)=>($l['trackedDocumentId']??'')===$i['id']));$i['lines']=array_map(function($l){unset($l['trackedDocumentId']);return $l;},$e['lines']);$i['lines']=array_merge($i['lines'],$own);$i['sourceEstimateId']=$e['id'];$i['sourceEstimate']=$e['number'];$i['total']=total($i);if($i['total']>99999999)throw new InvalidArgumentException('Linked invoice total is out of range.');return $i;}
function syncestimate(int $owner,array $old,array $next):?string{if($next['kind']!=='estimate')return null;$all=records($owner);$unique=count(array_filter($all,fn($r)=>$r['kind']==='estimate'&&$r['id']!==$next['id']&&$r['number']===$old['number']))===0;$skipped=[];foreach($all as $i)if($i['kind']==='invoice'&&(($i['sourceEstimateId']??'')===$next['id']||(empty($i['sourceEstimateId'])&&$unique&&($i['sourceEstimate']??'')===$old['number']))){if(paymentlocked($i)||running($i)){$skipped[]=$i['number'];continue;}$i=invoicefromestimate($next,$i);$i['updatedAt']=nowiso();saverecord($owner,$i);}return count($skipped)?'Estimate saved. '.implode(', ',$skipped).' was not updated because it has payments, an active payment link, or a running timer.':null;}
function cashupdate(array $r,array $p):array{if($r['kind']!=='invoice')throw new InvalidArgumentException('Invoice not found.');operation($p['operationId']??null);foreach($r['cashPayments']??[] as $old)if($old['id']===$p['operationId'])return $r;if(!empty($r['sessionId'])||!empty($r['checkoutPending']))throw new InvalidArgumentException('Refresh or cancel the Stripe payment link before receiving cash.');if(running($r))throw new InvalidArgumentException('Clock out before receiving payment.');if($r['status']==='Paid')throw new InvalidArgumentException('Invoice is already paid.');$amount=$p['amount']??null;if(!is_int($amount)||$amount<=0||$amount>$r['total']-paidamount($r))throw new InvalidArgumentException('Enter a cash amount no more than the balance due.');$date=$p['date']??'';if(!is_string($date)||!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/',$date,$m)||!checkdate((int)$m[2],(int)$m[3],(int)$m[1]))throw new InvalidArgumentException('Enter a valid payment date.');$r['cashPayments'][]=['id'=>$p['operationId'],'amount'=>$amount,'date'=>$date,'method'=>'Cash','recordedAt'=>nowiso()];$r['status']=paystatus($r);$r['paymentMethod']=methodlabel($r);return $r;}
function verifypayment(array $r,array $s):array{
 foreach($r['stripePayments']??[] as $p)if($p['id']===($s['id']??''))return $r;
 if(empty($r['sessionId'])&&!empty($r['checkoutPending'])&&($s['metadata']['checkout_operation']??'')===$r['checkoutPending']['id']){$r['sessionId']=$s['id'];$r['stripeAmount']=$r['checkoutPending']['amount'];unset($r['checkoutPending']);}
 if(($s['id']??'')!==($r['sessionId']??''))throw new InvalidArgumentException('Stripe session does not match this invoice.');
 $expected=$r['stripeAmount']??$r['total'];if(($s['amount_total']??-1)!==$expected||($s['currency']??'')!=='usd'||($s['metadata']['invoice_id']??'')!==$r['id'])throw new InvalidArgumentException('Stripe payment amount or invoice does not match.');
 if(($s['payment_status']??'')==='paid'){if($expected>$r['total']-paidamount($r))throw new InvalidArgumentException('Payment exceeds remaining balance.');$r['stripePayments'][]=['id'=>$s['id'],'amount'=>$expected,'date'=>gmdate('c',$s['created']??time()),'method'=>'Stripe','recordedAt'=>nowiso()];unset($r['sessionId'],$r['paymentUrl'],$r['stripeAmount']);$r['checkoutGeneration']=($r['checkoutGeneration']??0)+1;$r['status']=paystatus($r);$r['paymentMethod']=methodlabel($r);}
 elseif(($s['status']??'')==='expired'){unset($r['sessionId'],$r['paymentUrl'],$r['stripeAmount']);$r['checkoutGeneration']=($r['checkoutGeneration']??0)+1;}return $r;
}
function messageconfig():array{global $cfg;return ['sms'=>!empty($cfg['twilio_account_sid'])&&!empty($cfg['twilio_auth_token'])&&!empty($cfg['twilio_messaging_service_sid']),'email'=>!empty($cfg['resend_api_key'])&&!empty($cfg['message_from_email'])];}
function phonenum(string $s):string{$p=preg_replace('/[\s().-]/','',$s);if(preg_match('/^\d{10}$/',$p))$p='+1'.$p;elseif(preg_match('/^1\d{10}$/',$p))$p='+'.$p;if(!preg_match('/^\+[1-9]\d{7,14}$/',$p))throw new InvalidArgumentException('Enter a valid phone number with country code.');return $p;}
function messageprepare(array $r,array $p):array{if(!in_array($r['kind'],['job','estimate','invoice']))throw new InvalidArgumentException('Select an estimate or invoice.');$channel=$p['channel']??'';$action=$p['action']??'';if(!in_array($channel,['sms','email'])||!in_array($action,['draft','send']))throw new InvalidArgumentException('Select a valid message action.');operation($p['operationId']??null);$body=$p['body']??null;if(!is_string($body)||trim($body)===''||strlen($body)>($channel==='sms'?1600:20000))throw new InvalidArgumentException('Enter a message within the text/email character limit.');$to=$channel==='sms'?phonenum($r['phone']??''):trim($r['email']??'');if($channel==='email'&&!filter_var($to,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Add a valid customer email.');return ['id'=>'message-'.$p['operationId'].'-'.$channel,'kind'=>'message','recordId'=>$r['id'],'customerId'=>$r['customerId']??'','customer'=>$r['customer'],'vehicle'=>$r['vehicle']??'','channel'=>$channel,'recipient'=>$to,'body'=>trim($body),'status'=>$action==='draft'?'Draft':'Sending','createdAt'=>nowiso(),'subject'=>($r['kind']==='estimate'?'Estimate':($r['kind']==='invoice'?'Invoice':'Vehicle update')).' · '.$r['number']];}
function dispatchmessage(array $m):array{global $cfg;if(!messageconfig()[$m['channel']]){$m['status']='Not sent';$m['error']='Connect the sending service in private/config.php first.';return $m;}$c=null;try{$headers=[];if($m['channel']==='sms'){$c=curl_init('https://api.twilio.com/2010-04-01/Accounts/'.rawurlencode($cfg['twilio_account_sid']).'/Messages.json');$body=http_build_query(['To'=>$m['recipient'],'MessagingServiceSid'=>$cfg['twilio_messaging_service_sid'],'Body'=>$m['body']]);$headers=['Authorization: Basic '.base64_encode($cfg['twilio_account_sid'].':'.$cfg['twilio_auth_token']),'Content-Type: application/x-www-form-urlencoded'];}else{$c=curl_init('https://api.resend.com/emails');$body=json_encode(['from'=>$cfg['message_from_email'],'to'=>[$m['recipient']],'subject'=>$m['subject'],'text'=>$m['body'],'html'=>'<div style="white-space:pre-wrap;font-family:Arial">'.h($m['body']).'</div>'],JSON_THROW_ON_ERROR);$headers=['Authorization: Bearer '.$cfg['resend_api_key'],'Content-Type: application/json','Idempotency-Key: '.$m['id']];}curl_setopt_array($c,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_HTTPHEADER=>$headers,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20]);$raw=curl_exec($c);$code=curl_getinfo($c,CURLINFO_RESPONSE_CODE);$data=$raw!==false?json_decode($raw,true):null;if($raw===false||!is_array($data))throw new RuntimeException('Unconfirmed send.');if($code<300&&!empty($data['id']??$data['sid']??null)){$m['status']='Submitted';$m['providerId']=$data['id']??$data['sid'];$m['providerStatus']=$data['status']??'accepted';}else{$m['status']='Failed';$m['error']=$data['message']??'Provider rejected the message.';}}catch(Throwable $e){$m['status']='Unknown';$m['error']='Sending was interrupted. Check the provider before sending again to avoid a duplicate.';}finally{if($c)curl_close($c);}$m['updatedAt']=nowiso();return $m;}
function lockowner(int $owner):void{$q=db()->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$q->execute([$owner]);if(!$q->fetchColumn())throw new InvalidArgumentException('Owner account not found.');}
function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);$h=bin2hex($b);return substr($h,0,8).'-'.substr($h,8,4).'-'.substr($h,12,4).'-'.substr($h,16,4).'-'.substr($h,20);}
